example.code:
#include <iostream>
#include <queue>
#include <string>

int main() {
    std::queue<std::string> jobs;
    jobs.push("a.pdf");
    jobs.push("b.doc");
    jobs.push("c.png");
    std::cout << jobs.size() << '\n';
    std::cout << jobs.front() << ' ' << jobs.back() << '\n';

    bool retried = false;
    while (!jobs.empty()) {
        std::string job = jobs.front();
        jobs.pop();
        if (job == "b.doc" && !retried) {
            retried = true;
            std::cout << "Retry " << job << '\n';
            jobs.push(job);
        } else {
            std::cout << "Printing " << job << '\n';
        }
    }
    return 0;
}

