    }
    std::cout << '\n';
}

int main() {
    const std::vector<std::string> visits = {"home", "news", "sports", "weather", "mail"};
    std::deque<std::string> recent;
    for (const auto& page : visits) {
        recent.push_back(page);
        if (recent.size() > 3) {
            recent.pop_front();
        }
        printWindow(recent);
    }

    recent.push_front("start");
    std::cout << recent.front() << ' ' << recent.back() << '\n';
    recent.pop_back();
    std::cout << recent.front() << ' ' << recent.back() << '\n';
    return 0;
}

