#include <functional>
#include <iostream>
#include <queue>
#include <string>
#include <utility>
#include <vector>

using Offer = std::pair<int, std::string>;

int main() {
    const std::vector<int> scores = {55, 91, 78, 99, 64};
    std::priority_queue<int> maxHeap;
    for (int s : scores) {
        maxHeap.push(s);
    }
    std::string line = "";
    for (int i = 0; i < 3 && !maxHeap.empty(); ++i) {
        int s = maxHeap.top();
        maxHeap.pop();
        if (!line.empty()) {
            line += ' ';
        }
        line += std::to_string(s);
    }
    std::cout << line << '\n';

    std::priority_queue<Offer, std::vector<Offer>, std::greater<Offer>> offers;
    offers.push({4, "pen"});
    offers.push({12, "book"});
    offers.push({2, "eraser"});
    offers.push({7, "ruler"});
    offers.push({2, "clip"});
    for (int i = 0; i < 2 && !offers.empty(); ++i) {
        auto [price, item] = offers.top();
        offers.pop();
        std::cout << item << " costs " << price << '\n';
    }
    return 0;
}
